INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass alle flexibel strukturierten Daten immer hierarchisch organisiert sind?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch flache Strukturen haben"}, {"text": "Ja", "correct": false, "because": "Nicht immer hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wird häufig für solche Daten verwendet?', 3, '[{"text": "JSON", "correct": true, "because": "Leichtgewicht und flexibel"}, {"text": "CSV", "correct": false, "because": "Strukturierte Daten"}, {"text": "MP3", "correct": false, "because": "Für Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen diese Daten flexibel?', 5, '[{"text": "Selbstbeschreibend", "correct": true, "because": "Enthält Metadaten"}, {"text": "Schemalos", "correct": true, "because": "Keine feste Struktur"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenfaktor"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) XML ist ein Format für solche Daten. b) Es erfordert immer ein festes Schema.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schema optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verarbeitung solcher Daten?', 4, '[{"text": "Datenstruktur", "correct": false, "because": "Bestimmt Verarbeitung"}, {"text": "Metadaten", "correct": false, "because": "Beschreiben Inhalt"}, {"text": "Dateifarbe", "correct": true, "because": "Kein Datenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Daten immer in relationalen Datenbanken gespeichert werden?', 2, '[{"text": "Nein", "correct": true, "because": "NoSQL-Datenbanken üblich"}, {"text": "Ja", "correct": false, "because": "Flexible Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenbank eignet sich für solche Daten?', 4, '[{"text": "MongoDB", "correct": true, "because": "Unterstützt schemalose Daten"}, {"text": "MySQL", "correct": false, "because": "Für relationale Daten"}, {"text": "SQLite", "correct": false, "because": "Strukturierte Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Daten immer unstrukturiert sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Zwischen strukturiert und unstrukturiert"}, {"text": "Ja", "correct": false, "because": "Teilweise strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Daten schwer zu analysieren?', 2, '[{"text": "Nein", "correct": true, "because": "Werkzeuge wie JSON-Parser helfen"}, {"text": "Ja", "correct": false, "because": "Analyse machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate sind für solche Daten typisch?', 5, '[{"text": "JSON", "correct": true, "because": "Flexibel und weit verbreitet"}, {"text": "XML", "correct": true, "because": "Selbstbeschreibend"}, {"text": "TXT", "correct": false, "because": "Unstrukturiert"}, {"text": "PDF", "correct": false, "because": "Dokumentenformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verarbeitung solcher Daten?', 4, '[{"text": "Strukturvalidierung", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnelle Speicherung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Farbliche Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NoSQL-Datenbanken eignen sich für solche Daten. b) Sie sind immer relational.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nicht relational"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Analyse solcher Daten?', 3, '[{"text": "Parser", "correct": false, "because": "Verarbeitet Struktur"}, {"text": "Metadaten", "correct": false, "because": "Beschreiben Inhalt"}, {"text": "Diagrammfarben", "correct": true, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich solche Daten in MongoDB speichere?', 4, '[{"text": "Als JSON-Dokumente", "correct": true, "because": "MongoDB nutzt BSON"}, {"text": "Als Tabellen", "correct": false, "because": "Relationale Struktur"}, {"text": "Ohne Format", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Daten immer kleiner als strukturierte sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Größe variiert"}, {"text": "Ja", "correct": false, "because": "Kein fester Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, solche Daten effizient zu verarbeiten?', 4, '[{"text": "Schema-on-read", "correct": true, "because": "Flexibilität bei Analyse"}, {"text": "Feste Tabellen", "correct": false, "because": "Zu starr"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Daten immer unstrukturiert?', 2, '[{"text": "Nein", "correct": true, "because": "Teilweise strukturiert"}, {"text": "Ja", "correct": false, "because": "Zwischenform"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten solche Daten?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Anpassbare Struktur"}, {"text": "Einfache Erweiterung", "correct": true, "because": "Keine Schemaänderung nötig"}, {"text": "Hohe Speicherkosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Einheitliche Größe", "correct": false, "because": "Variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung solcher Daten unwichtig?', 3, '[{"text": "Struktur", "correct": false, "because": "Bestimmt Verarbeitung"}, {"text": "Validierung", "correct": false, "because": "Sichert Konsistenz"}, {"text": "Dateiname", "correct": true, "because": "Kein Datenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich solche Daten analysiere?', 4, '[{"text": "Parser nutzen, Struktur prüfen", "correct": true, "because": "Ermöglicht Zugriff"}, {"text": "Nur speichern", "correct": false, "because": "Fehlt Analyse"}, {"text": "Ohne Tools nutzen", "correct": false, "because": "Ineffizient"}]');
